test_suite:
test('groups by a string key', () => {
  const items = [{ type: 'a' }, { type: 'b' }, { type: 'a' }];
  const result = groupBy(items, 'type');
  expect(result.a).toHaveLength(2);
  expect(result.b).toHaveLength(1);
});

test('preserves items in each group', () => {
  const items = [{ id: 1, cat: 'x' }, { id: 2, cat: 'x' }];
  const result = groupBy(items, 'cat');
  expect(result.x[0].id).toBe(1);
  expect(result.x[1].id).toBe(2);
});

test('returns empty object for empty array', () => {
  expect(groupBy([], 'key')).toEqual({});
});

test('groups by numeric values', () => {
  const items = [{ score: 1 }, { score: 2 }, { score: 1 }];
  const result = groupBy(items, 'score');
  expect(Object.keys(result)).toHaveLength(2);
});

// __hidden__
test('single-item groups work correctly', () => {
  const items = [{ type: 'unique' }];
  expect(groupBy(items, 'type')).toEqual({ unique: [{ type: 'unique' }] });
});

solution:
export function groupBy(arr, key) {
  return arr.reduce((groups, item) => {
    const groupKey = item[key];
    if (!groups[groupKey]) groups[groupKey] = [];
    groups[groupKey].push(item);
    return groups;
  }, {});
}
